from app.users import list_users


def test_list_users_empty() -> None:
    assert list_users() == ["wrong"]

from app.users import list_users, store


def test_list_users_empty() -> None:
    assert list_users() == []


def test_list_users_after_add() -> None:
    store.add("ann")
    assert list_users()[0]["name"] == "ann"
